_CRED = "(1000000026, 1000000024, 1000000092, 1000000025)"
SSRK_OTSD_OPEN_01: tuple[Dataset, ...] = (
    Dataset("o2_open_items_live", "extract", "Open creditor items from live FINPOST (pending <> 0) on the four creditor ledgers, with sub-ledger, class and ledger names.",
            sql=("SELECT p.postcode, p.entcode, p.entno, p.entdt, p.enttype, p.docno, p.docdt, p.duedt, p.glcode, g.glname, p.slcode, s.slid, s.slname, s.clscode, k.clsname, k.clstype, s.crdays, s.ext AS sl_ext, "
                 "p.damount, p.camount, p.adjamt, p.release_status, p.admsite_code_owner "
                 "FROM SSRK.FINPOST p JOIN SSRK.FINGL g ON g.glcode = p.glcode LEFT JOIN SSRK.FINSL s ON s.slcode = p.slcode LEFT JOIN SSRK.ADMCLS k ON k.clscode = s.clscode "
                 f"WHERE p.entdt >= DATE '2016-01-01' AND p.glcode IN {_CRED} AND ABS(NVL(p.damount, 0) - NVL(p.camount, 0)) <> NVL(p.adjamt, 0) "
                 "ORDER BY p.postcode FETCH FIRST 40000 ROWS ONLY")),
)
